'use strict';
(()=>{
const nav=[...document.querySelectorAll('aside nav button')].find(b=>b.textContent.trim()==='Аналитика');nav.disabled=false;
const page=document.createElement('main');page.hidden=true;page.id='campaign-statistics';
page.innerHTML=`<div class="breadcrumb">Коммуникации / Аналитика</div><div class="heading"><div><h1>Статистика рассылок</h1><p>Доставка, открытия, переходы и отписки</p></div><button class="outline" id="stats-demo">Заполнить тестовыми событиями</button></div>
<div class="demo"><b>Только тестовые события</b><span>Эти показатели не подтверждают реальную отправку. Тестовые отписки и ошибки не меняют клиентскую базу и запреты.</span></div>
<section class="panel"><h2>Период и рассылка</h2><form id="stats-filters" class="stats-filter-grid"><label>Рассылка<select id="stats-campaign" aria-label="Рассылка для статистики"><option value="demo">Демонстрационный набор</option><option value="all">Все рассылки</option></select></label><label>С даты<input id="stats-from" type="date"></label><label>По дату включительно<input id="stats-to" type="date"></label><button class="outline" type="submit">Показать</button><button class="outline" type="button" id="stats-reset">Сбросить период</button></form><p id="stats-label"></p></section>
<section class="stats" id="stats-cards" aria-label="Показатели тестовой рассылки"></section>
<p class="footnote">Доставка — событие приёма сервером получателя; попадание во «Входящие» не подтверждается. Открытие — загрузка пикселя, а не подтверждение прочтения. В этом подэтапе все события синтетические.</p>
<section class="panel"><h2>Доли получателей</h2><div id="stats-rates" class="stats-rate-grid"></div><p>Доставка и ошибки — среди переданных на отправку. Открытия, переходы и отписки — среди доставленных. Учитываются получатели с обоими событиями в выбранном периоде; отсутствующие события не восстанавливаются автоматически. «—» означает отсутствие базы для расчёта.</p></section>
<section class="panel"><h2>Динамика по дням</h2><div id="stats-days" class="table-scroll"></div><p>Уникальные получатели за день. Один получатель может учитываться в нескольких днях; сумма дневных значений может отличаться от общего числа уникальных получателей. Показываются последние 90 дней с событиями выбранного периода.</p></section>
<section class="panel"><h2>Переходы по ссылкам</h2><div id="stats-links" class="table-scroll"></div><p>До 20 ссылок с наибольшим числом переходов. Повторные клики учитываются отдельно от уникальных получателей.</p></section>
<section class="panel"><h2>Ошибки</h2><div id="stats-errors"></div><p>Получатель с временной ошибкой может позднее получить письмо. Ошибки и доставка не являются взаимоисключающими категориями.</p></section>
<section class="panel"><h2>Журнал тестовых событий</h2><form id="stats-log-filters" class="stats-filter-grid"><label>Тип события в журнале<select id="stats-kind" aria-label="Тип события в журнале"><option value="">Все события</option></select></label><label>Email в журнале<input id="stats-query" type="search"></label><label>Сортировка по времени<select id="stats-direction" aria-label="Сортировка по времени"><option value="desc">Сначала новые</option><option value="asc">Сначала старые</option></select></label><button class="outline">Применить к журналу</button></form><p>Эти фильтры меняют только журнал; показатели выше рассчитаны по рассылке и периоду.</p><div id="stats-history" class="table-scroll"></div><div class="actions"><button class="outline" id="stats-prev">Назад</button><span id="stats-pagination"></span><button class="outline" id="stats-next">Далее</button></div></section>
<section class="panel"><details><summary>Добавить одно тестовое событие</summary><p>Выберите конкретную рассылку или демонстрационный набор. Повтор запроса с тем же идентификатором не добавит дубль.</p><form id="stats-event-form" class="stats-event-grid"><label>Email тестового получателя<input name="recipient" type="email" maxlength="254" required placeholder="recipient@example.invalid"></label><label>Событие<select name="kind" aria-label="Добавляемое событие"></select></label><label>Время события (необязательно)<input name="occurred_at" type="datetime-local"></label><label id="stats-event-link" hidden>Ссылка перехода<input name="link" type="url" maxlength="2000" placeholder="https://example.invalid/offers"></label><label id="stats-event-error" hidden>Вид ошибки<select name="error_type"><option value="temporary">Временная</option><option value="permanent">Окончательная</option></select></label><label>Описание<input name="detail" maxlength="500"></label><button class="outline" id="stats-add-event">Добавить тестовое событие</button></form><p role="status" id="stats-event-status"></p></details></section><p role="status" id="stats-status"></p>`;
document.body.append(page);const activityButton=document.createElement('button');activityButton.className='outline';activityButton.textContent='Аудитории по активности (тест)';activityButton.onclick=()=>window.ActivityAudiences.open('statistics',$('campaign').value);page.querySelector('.heading').append(activityButton);const style=document.createElement('style');style.textContent=`#campaign-statistics label{display:block;margin:8px 0}#campaign-statistics input,#campaign-statistics select{display:block;width:100%;box-sizing:border-box}#campaign-statistics button{width:auto;flex:none;min-height:36px}.stats-filter-grid,.stats-event-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;align-items:end}.stats-rate-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:10px}.stats-rate-grid>div{padding:14px;background:#f3f8fc;border-radius:6px}.stats-rate-grid strong{display:block;font-size:24px;margin:6px 0}#campaign-statistics .stats{grid-template-columns:repeat(auto-fit,minmax(145px,1fr))}#campaign-statistics td,#campaign-statistics th{padding:12px;text-align:left;word-break:break-word}#campaign-statistics input:focus,#campaign-statistics select:focus{outline:none;border-color:#6BAEE0;box-shadow:0 0 0 2px #0795e918}#campaign-statistics .actions{align-items:center}`;document.head.append(style);
const $=id=>document.getElementById('stats-'+id),kinds={sent:'Передано на отправку',delivered:'Доставлено',open:'Открытия',click:'Переходы',unsubscribe:'Отписки',error:'Ошибки'};
let currentPage=1,requestId=0,pendingSelection=null,eventToken=null;
const eventForm=$('event-form');for(const [key,label]of Object.entries(kinds)){$('kind').add(new Option(label,key));eventForm.elements.kind.add(new Option(label,key));}
function element(tag,value){const e=document.createElement(tag);e.textContent=value;return e;}
function table(host,headers,rows){host.replaceChildren();if(!rows.length){host.textContent='Нет событий за выбранный период.';return;}const t=document.createElement('table'),head=document.createElement('tr');for(const h of headers)head.append(element('th',h));t.append(head);for(const values of rows){const tr=document.createElement('tr');for(const v of values)tr.append(element('td',String(v??'—')));t.append(tr);}host.append(t);}
function selection(){return $('campaign').value==='demo'?'demo':$('campaign').value==='all'?'all':Number($('campaign').value);}
function remember(){try{sessionStorage.setItem('statistics-filters',JSON.stringify(Object.fromEntries(['campaign','from','to','kind','query','direction'].map(key=>[key,$(key).value]))));}catch{}}
async function options(){const desired=pendingSelection||$('campaign').value||'demo';pendingSelection=null;const data=await api('/api/campaigns');$('campaign').replaceChildren(new Option('Демонстрационный набор','demo'),new Option('Все рассылки','all'));for(const c of data.campaigns)$('campaign').add(new Option(c.name,String(c.id)));if(!['all','demo'].includes(desired)&&!data.campaigns.some(c=>String(c.id)===desired)){try{const row=await api('/api/campaigns/'+desired);$('campaign').add(new Option(row.name,String(row.id)));}catch{}}$('campaign').value=[...$('campaign').options].some(o=>o.value===desired)?desired:'demo';syncButtons();}
function syncButtons(){const all=selection()==='all';$('demo').disabled=all;$('add-event').disabled=all;}
async function load(){const request=++requestId;remember();$('status').textContent='Загрузка статистики…';const params=new URLSearchParams({campaign_id:$('campaign').value,from:$('from').value,to:$('to').value,kind:$('kind').value,query:$('query').value,direction:$('direction').value,page:String(currentPage)});try{const data=await api('/api/campaign-stats?'+params);if(request!==requestId)return;currentPage=data.pagination.page;$('label').textContent=`${data.label} · Тестовые события · Часовой пояс: ${data.timezone}`;$('cards').replaceChildren();for(const [key,label]of Object.entries(kinds)){const box=document.createElement('article');box.append(element('span',label),element('strong',String(data.unique[key])),element('small',`Уникальных получателей · событий: ${data.totals[key]}`));$('cards').append(box);}$('rates').replaceChildren();for(const [key,label]of Object.entries({delivery:'Доставка',open:'Открытия',click:'Переходы',unsubscribe:'Отписки',error:'Ошибки'})){const box=element('div',label);box.append(element('strong',data.rates[key]===null?'—':data.rates[key].toLocaleString('ru-RU')+'%'));$('rates').append(box);}
 table($('days'),['Дата',...Object.values(kinds)],data.days.map(row=>[row.day,...Object.keys(kinds).map(key=>row[key])]));table($('links'),['Ссылка','Все переходы','Уникальных получателей'],data.links.map(row=>[row.link,row.total,row.unique]));table($('errors'),['Вид ошибки','Всего событий','Уникальных получателей'],data.errors.map(row=>[row.error_type==='temporary'?'Временная':'Окончательная',row.total,row.unique]));table($('history'),['Время','Рассылка / набор','Получатель','Событие','Ссылка / вид ошибки','Описание'],data.history.map(row=>[new Date(row.occurred_at).toLocaleString('ru-RU',{timeZone:data.timezone}),row.campaign,row.recipient,kinds[row.kind],row.link||(row.error_type==='temporary'?'Временная':row.error_type==='permanent'?'Окончательная':''),row.detail]));$('pagination').textContent=`${data.pagination.page} / ${data.pagination.pages} · событий: ${data.pagination.total}`;$('prev').disabled=!data.pagination.has_previous;$('next').disabled=!data.pagination.has_next;$('status').textContent='';syncButtons();}catch(e){if(request===requestId)$('status').textContent=e.message;}}
$('filters').onsubmit=e=>{e.preventDefault();currentPage=1;load();};$('log-filters').onsubmit=e=>{e.preventDefault();currentPage=1;load();};$('campaign').onchange=()=>{currentPage=1;eventToken=null;syncButtons();load();};$('reset').onclick=()=>{$('from').value='';$('to').value='';currentPage=1;load();};$('prev').onclick=()=>{currentPage=Math.max(1,currentPage-1);load();};$('next').onclick=()=>{currentPage++;load();};
$('demo').onclick=async()=>{const button=$('demo');button.disabled=true;try{await api('/api/campaign-stats/demo',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({campaign_id:selection()})});$('from').value='';$('to').value='';$('kind').value='';$('query').value='';currentPage=1;await load();$('status').textContent='Тестовый набор готов. Повторное заполнение не создаёт дубли. Письма не отправлялись.';}catch(e){$('status').textContent=e.message;}finally{syncButtons();}};
function syncEvent(){const kind=eventForm.elements.kind.value;$('event-link').hidden=kind!=='click';$('event-error').hidden=kind!=='error';eventForm.elements.link.required=kind==='click';}
eventForm.elements.kind.onchange=syncEvent;eventForm.oninput=()=>{eventToken=null;};eventForm.onchange=()=>{eventToken=null;};eventForm.onsubmit=async e=>{e.preventDefault();if(selection()==='all')return;const button=$('add-event');button.disabled=true;try{eventToken=eventToken||crypto.randomUUID();const fields=Object.fromEntries(new FormData(eventForm));if(fields.kind!=='click')fields.link='';if(fields.kind!=='error')fields.error_type='';await api('/api/campaign-stats/test-events',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...fields,campaign_id:selection(),event_id:eventToken,source:'test'})});eventToken=null;eventForm.reset();syncEvent();$('event-status').textContent='Тестовое событие сохранено. Реальные подписки и статусы клиентов не изменены.';await load();}catch(e){$('event-status').textContent=e.message;}finally{syncButtons();}};syncEvent();
document.querySelector('aside nav').addEventListener('click',event=>{const target=event.target.closest('button');if(!target||target.disabled)return;if(target===nav){document.querySelectorAll('body>main').forEach(p=>p.hidden=true);page.hidden=false;document.querySelectorAll('aside nav button').forEach(b=>{b.classList.remove('active');b.removeAttribute('aria-current');});nav.classList.add('active');nav.setAttribute('aria-current','page');document.title='Статистика рассылок';try{sessionStorage.setItem('statistics-open','1');}catch{}options().then(load).catch(e=>$('status').textContent=e.message);}else{page.hidden=true;try{sessionStorage.removeItem('statistics-open');}catch{}}});
window.CampaignStatistics={open(id){pendingSelection=String(id);nav.click();}};
try{const saved=JSON.parse(sessionStorage.getItem('statistics-filters')||'null');if(saved){for(const key of ['from','to','kind','query','direction'])if(typeof saved[key]==='string')$(key).value=saved[key];pendingSelection=saved.campaign||null;}if(sessionStorage.getItem('statistics-open')==='1')nav.click();}catch{}
})();
